CREATE TABLE integrations_links (workspace_id TEXT NOT NULL, id TEXT NOT NULL, target_kind TEXT NOT NULL, target_id TEXT NOT NULL, kind TEXT NOT NULL, url TEXT NOT NULL, version INTEGER NOT NULL, active INTEGER NOT NULL, PRIMARY KEY(workspace_id,id));
CREATE TABLE integrations_sources (workspace_id TEXT NOT NULL, id TEXT NOT NULL, project_id TEXT NOT NULL, name TEXT NOT NULL, secret_hash TEXT NOT NULL, webhook_url TEXT, webhook_events TEXT NOT NULL, webhook_cipher TEXT, PRIMARY KEY(workspace_id,id));
CREATE TABLE integrations_feedback (workspace_id TEXT NOT NULL, id TEXT NOT NULL, source_id TEXT NOT NULL, delivery_id TEXT NOT NULL, project_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, issue_id TEXT, version INTEGER NOT NULL, received_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,source_id,delivery_id), FOREIGN KEY(workspace_id,source_id) REFERENCES integrations_sources(workspace_id,id));
CREATE TABLE integrations_deliveries (workspace_id TEXT NOT NULL, id TEXT NOT NULL, source_id TEXT NOT NULL, external_id TEXT NOT NULL, event_type TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL, next_attempt_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,source_id,external_id), FOREIGN KEY(workspace_id,source_id) REFERENCES integrations_sources(workspace_id,id));
CREATE TABLE integrations_receipts (workspace_id TEXT NOT NULL, principal_id TEXT NOT NULL, operation_id TEXT NOT NULL, fingerprint TEXT NOT NULL, result_id TEXT NOT NULL, PRIMARY KEY(workspace_id,principal_id,operation_id));
CREATE TABLE integrations_guards (workspace_id TEXT NOT NULL, id TEXT NOT NULL, changed INTEGER NOT NULL CHECK(changed=1), PRIMARY KEY(workspace_id,id));
CREATE TABLE integrations_history (workspace_id TEXT NOT NULL, id TEXT NOT NULL, action TEXT NOT NULL, actor_id TEXT NOT NULL, occurred_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,id));
CREATE TABLE integrations_events (workspace_id TEXT NOT NULL, id TEXT NOT NULL, aggregate_id TEXT NOT NULL, type TEXT NOT NULL, occurred_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,id));
